function validate([nums1, nums2, k]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  if (nums1.length !== nums2.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.length < 2 || nums1.length > 100000) return 'The arrays need 2 to 10^5 values.';
  const bad = v => !Number.isInteger(v) || v < 0 || v > 1000000000;
  if (nums1.some(bad) || nums2.some(bad)) return 'Each value is an integer between 0 and 10^9.';
  if (!Number.isInteger(k) || k < 0 || k > 100000) return 'k is an integer between 0 and 10^5.';
  return null;
}

