  let raise = 0;
  let lower = 0;

  for (let i = 0; i < nums1.length; i++) {
    const diff = nums2[i] - nums1[i];
    if (diff === 0) {
      continue;
    }
    if (k === 0 || diff % k !== 0) {
      return -1;
    }
    if (diff > 0) {
      raise += diff / k;
    } else {
      lower += -diff / k;
    }
  }

  return raise === lower ? raise : -1;
}

