function minOperations(nums1, nums2, k) {
  const cur = nums1.slice();
  const same = () => cur.every((v, i) => v === nums2[i]);
  if (k === 0) return same() ? 0 : -1;
  let ops = 0;
  while (!same()) {
    const up = cur.findIndex((v, i) => v + k <= nums2[i]);
    const down = cur.findIndex((v, i) => v - k >= nums2[i]);
    if (up < 0 || down < 0) return -1;
    cur[up] += k;
    cur[down] -= k;
    ops++;
  }
  return ops;
}

