function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 5);
  const cap = large ? 1000000000 : 20;
  const kPick = rand();
  let k;
  if (large) k = kPick < 0.4 ? 1 + Math.floor(rand() * 10) : 1 + Math.floor(rand() * 100000);
  else k = kPick < 0.1 ? 0 : 1 + Math.floor(rand() * 5);
  const nums1 = Array.from({ length: n }, () => Math.floor(rand() * (cap + 1)));
  const mode = rand();
  if (!large && mode < 0.2) {
    return [nums1, Array.from({ length: n }, () => Math.floor(rand() * (cap + 1))), k];
  }
  // Build a reachable nums2 by applying random moves of whole k steps, staying within [0, cap].
  const nums2 = nums1.slice();
  if (k > 0) {
    const steps = large ? 3000 : Math.floor(rand() * 6);
    for (let s = 0; s < steps; s++) {
      const i = Math.floor(rand() * n);
      const j = Math.floor(rand() * n);
      if (i === j) continue;
      const most = Math.min(Math.floor((cap - nums2[i]) / k), Math.floor(nums2[j] / k));
      if (most < 1) continue;
      const t = 1 + Math.floor(rand() * Math.min(most, large ? cap : 3));
      nums2[i] += t * k;
      nums2[j] -= t * k;
    }
  }
  // Sometimes break it: off by one (not a multiple of k) or off by k (sums no longer balance).
  if (mode > 0.8) {
    const i = Math.floor(rand() * n);
    const step = mode > 0.9 && k > 0 && k <= cap ? k : 1;
    nums2[i] = nums2[i] - step >= 0 ? nums2[i] - step : nums2[i] + step;
  }
  return [nums1, nums2, k];
}
